using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.USR.Marcas;using GraphApi.Services.USR.Marcas;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.USR.Marcas{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Marcas: creación, actualización y eliminación.")]    public class MarcasMutation    {        [Authorize]        [GraphQLName("createMarcas")]        [GraphQLDescription("Crea un nuevo Marca usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadMarcas> CreateMarcasAsync(            [GraphQLDescription("Datos necesarios para crear el Marca.")]            clCreateMarcas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Marca.")]            IMarcasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreateMarcas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updateMarcas")]        [GraphQLDescription("Actualiza los campos especificados de un Marca existente.")]        public async Task<clReadMarcas?> UpdateMarcasAsync(            [GraphQLDescription("Datos del Marca a actualizar.")]            clUpdateMarcas objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Marca.")]            IMarcasService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdateMarcas(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deleteMarcas")]        [GraphQLDescription("Elimina un Marca por su ID.")]        public async Task<bool> delMarcasAsync(            [GraphQLDescription("ID del Marca a eliminar.")]            int nMarcasID,            [Service]            [GraphQLDescription("Servicio para operaciones de Marca.")]            IMarcasService objService        )        {            return await objService.DeleteMarcas(nMarcasID);        }    }}